CREATE TABLE `bitirim_clothing_compatibility_rules` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `rule_id` varchar(191) NOT NULL,
  `from_component` tinyint(3) unsigned NOT NULL,
  `from_drawable` smallint(5) unsigned NOT NULL,
  `from_texture` smallint(6) NOT NULL DEFAULT -1,
  `from_collection` varchar(64) NOT NULL DEFAULT '',
  `to_component` tinyint(3) unsigned NOT NULL,
  `to_drawable` smallint(5) unsigned NOT NULL,
  `to_texture` smallint(6) NOT NULL DEFAULT -1,
  `to_collection` varchar(64) NOT NULL DEFAULT '',
  `status` enum('verified','rejected') NOT NULL,
  `priority` smallint(5) unsigned NOT NULL DEFAULT 0,
  `verified_by` varchar(128) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_from_to` (`from_component`,`from_drawable`,`from_texture`,`from_collection`,`to_component`,`to_drawable`,`to_texture`,`to_collection`)
) ENGINE=InnoDB AUTO_INCREMENT=2803 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
